{
  "bbb_prediction": "pass",
  "claims": [
    {
      "card_ids": ["C19"],
      "claim": "In mice, orally administered ibrutinib, the closest structural analog, rapidly penetrated the BBB with a brain-to-plasma ratio of 0.7, directly supporting meaningful CNS access.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C11"],
      "claim": "In humans, ibrutinib showed a protein-binding-corrected CSF/plasma ratio of 28.7%, indicating significant CNS penetration of free drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "In rats, JNJ-39220675 crossed the BBB after subcutaneous administration and occupied central H3 receptors, with an average brain-to-plasma ratio of 3.4.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "Multiple structurally similar molecules, including the closest analog ibrutinib, demonstrate direct CNS access after systemic administration across mice, rats, monkeys, and humans via brain-to-plasma ratios, CSF penetration, and brain uptake. The single negative efflux-restricted sotorasib record is low-similarity and insufficient to override the consistent positive evidence; therefore predict pass.",
  "evidence_gaps": [
    "No direct query-specific CNS exposure data; prediction relies on analog evidence with Morgan similarities of 0.24–0.37.",
    "One human ibrutinib CSF/plasma measurement was low before protein-binding correction, but corrected values and multiple other direct measures support CNS access.",
    "The negative sotorasib record reflects ABCB1 efflux restriction in mice and has low similarity to the query, limiting transferability."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

